using DriveOS.Modules.Workforce.Domain.Timesheets; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;
internal sealed class TimesheetConfiguration:IEntityTypeConfiguration<Timesheet>
{
 public void Configure(EntityTypeBuilder<Timesheet> b){b.ToTable("timesheets");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new TimesheetId(x));b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.EmployeeId).HasConversion(x=>x.Value,x=>new EmployeeId(x));b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.SubmittedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.ReviewerUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.DecidedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LockedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.DecisionReason).HasMaxLength(1024);b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.PeriodFrom,x.PeriodTo});b.HasIndex(x=>new{x.OrganizationId,x.Status});b.OwnsMany(x=>x.Entries,e=>{e.ToTable("timesheet_entries");e.WithOwner().HasForeignKey("timesheet_id");e.HasKey(x=>x.Id);e.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new TimesheetEntryId(x));e.Property(x=>x.ActivityType).HasConversion<int>();e.Property(x=>x.Source).HasConversion<int>();e.Property(x=>x.Hours).HasPrecision(8,2);e.Property(x=>x.Description).HasMaxLength(512);e.Property(x=>x.SourceReference).HasMaxLength(128);e.HasIndex("timesheet_id", "Date");}); b.Navigation(x=>x.Entries).UsePropertyAccessMode(PropertyAccessMode.Field);}
}
